% database in the database command.

% Auto-generated by MATLAB (R2022b) and Database Toolbox Version 10.4 on 13-Apr-2023 14:40:07

%% Make connection to database
conn = database(DBname,'','');
query = cell(1,5);
switch author
    case 1
